def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    foreground = next(v for row in grid for v in row if v != 8)
    # The long line segments (three or more original marks) are linked across
    # their gaps. Do vertical links first; horizontal segments can then extend
    # to the ends of those vertical links at crossings.
    for c in range(w):
        ys = [r for r in range(h) if grid[r][c] == foreground]
        if len(ys) >= 3:
            for r in range(min(ys), max(ys) + 1):
                if out[r][c] == 8:
                    out[r][c] = 2
    for r in range(h):
        original = [c for c, v in enumerate(grid[r]) if v == foreground]
        if len(original) >= 3:
            xs = [c for c, v in enumerate(out[r]) if v in (foreground, 2)]
            for c in range(min(xs), max(xs) + 1):
                if out[r][c] == 8:
                    out[r][c] = 2
    return out

