 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    foreground = next(v for v in counts if v != background)
    out = [row[:] for row in grid]
    # Mark the gaps between aligned foreground cells in each row/column.
    for r in range(h):
        xs = [c for c, value in enumerate(grid[r]) if value == foreground]
        if len(xs) >= 2:
            for c in range(min(xs), max(xs) + 1):
                if grid[r][c] == background:
                    out[r][c] = 2
    for c in range(w):
        ys = [r for r in range(h) if grid[r][c] == foreground]
        if len(ys) >= 2:
            for r in range(min(ys), max(ys) + 1):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out
